import React, { createContext, useState, useContext, useEffect, useCallback } from 'react';
import { useModal } from './ModalContext';

const AuthContext = createContext();

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

export const AuthProvider = ({ children }) => {
  const { showModal } = useModal();
  const [user, setUser] = useState(null);
  const [token, setToken] = useState(null);
  const [cart, setCart] = useState([]);
  const [favorites, setFavorites] = useState([]);
  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(true);

  const normalizeProduct = (product) => {
    if (product.images && Array.isArray(product.images) && product.images.length > 0) return product;
    if (product.image && typeof product.image === 'string') return { ...product, images: [product.image] };
    return { ...product, images: ['/images/placeholder.jpg'] };
  };

  // Восстановление сессии
  useEffect(() => {
    const initializeAuth = async () => {
      setLoading(true);
      const savedToken = localStorage.getItem('auth_token');
      const savedUser = localStorage.getItem('auth_user');

      if (savedToken && savedUser) {
        try {
          setToken(savedToken);
          setUser(JSON.parse(savedUser));
        } catch (error) {
          console.error('Error restoring session:', error);
          localStorage.removeItem('auth_token');
          localStorage.removeItem('auth_user');
        }
      }
      setLoading(false);
    };

    initializeAuth();
  }, []);

  // Регистрация
  const register = useCallback(async (userData) => {
    try {
      const formData = new FormData();
      formData.append('username', userData.username);
      formData.append('email', userData.email);
      formData.append('password', userData.password);

      const response = await fetch('https://luna-aurea.ru/api/index.php?route=register', {
        method: 'POST',
        body: formData,
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.error || 'Registration failed');
      }

      setToken(data.token);
      setUser(data.user);
      localStorage.setItem('auth_token', data.token);
      localStorage.setItem('auth_user', JSON.stringify(data.user));

      return data;
    } catch (error) {
      console.error('Registration error:', error);
      throw error;
    }
  }, []);

  // Вход
  const login = useCallback(async (email, password) => {
    try {
      const formData = new FormData();
      formData.append('email', email);
      formData.append('password', password);

      const response = await fetch('https://luna-aurea.ru/api/index.php?route=login', {
        method: 'POST',
        body: formData,
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.error || 'Login failed');
      }

      setToken(data.token);
      setUser(data.user);
      localStorage.setItem('auth_token', data.token);
      localStorage.setItem('auth_user', JSON.stringify(data.user));

      return data;
    } catch (error) {
      console.error('Login error:', error);
      throw error;
    }
  }, []);

  // Быстрый вход
  const quickLogin = useCallback(async () => {
    try {
      return await login('demo@luna-aurea.com', 'demo123');
    } catch (error) {
      await register({ username: 'DemoUser', email: 'demo@luna-aurea.com', password: 'demo123' });
      return await login('demo@luna-aurea.com', 'demo123');
    }
  }, [login, register]);

  // Выход
  const logout = useCallback(() => {
    localStorage.removeItem('auth_token');
    localStorage.removeItem('auth_user');
    setToken(null);
    setUser(null);
    setCart([]);
    setFavorites([]);
    setOrders([]);
  }, []);

  // Добавление в корзину
  const addToCart = useCallback((product) => {
    const normalized = normalizeProduct(product);
    const existing = cart.find(item => item.id === normalized.id);
    let newCart;
    let message = '';

    if (existing) {
      newCart = cart.map(item =>
        item.id === normalized.id ? { ...item, quantity: (item.quantity || 1) + 1 } : item
      );
      message = `Количество "${normalized.name}" увеличено!`;
    } else {
      newCart = [...cart, { ...normalized, quantity: 1 }];
      message = `"${normalized.name}" добавлен в корзину!`;
    }

    setCart(newCart);
    showModal('cart', normalized, message);
  }, [cart, showModal]);

  const removeFromCart = useCallback((productId) => {
    setCart(cart.filter(item => item.id !== productId));
  }, [cart]);

  const addToFavorites = useCallback((product) => {
    const normalized = normalizeProduct(product);
    if (!favorites.some(item => item.id === normalized.id)) {
      const newFav = [...favorites, normalized];
      setFavorites(newFav);
      showModal('favorites', normalized, `"${normalized.name}" добавлен в избранное!`);
      return true;
    }
    return false;
  }, [favorites, showModal]);

  const removeFromFavorites = useCallback((productId) => {
    setFavorites(favorites.filter(item => item.id !== productId));
  }, [favorites]);

  const isInFavorites = useCallback((productId) => {
    return favorites.some(item => item.id === productId);
  }, [favorites]);

  const createOrder = useCallback((orderData) => {
    const newOrder = {
      id: Date.now().toString(),
      date: new Date().toLocaleString('ru-RU'),
      items: [...cart],
      total: cart.reduce((sum, item) => sum + (item.price * (item.quantity || 1)), 0),
      status: 'pending',
      address: orderData.address,
      cardNumber: orderData.cardNumber,
    };
    setOrders([newOrder, ...orders]);
    setCart([]);
    return newOrder;
  }, [cart, orders]);

  const cancelOrder = useCallback((orderId) => {
    setOrders(orders.map(order =>
      order.id === orderId ? { ...order, status: 'cancelled' } : order
    ));
  }, [orders]);

  const isAuthenticated = useCallback(() => {
    return !!user && !!token;
  }, [user, token]);

  return (
    <AuthContext.Provider value={{
      user,
      token,
      cart,
      favorites,
      orders,
      loading,
      register,
      login,
      quickLogin,
      logout,
      isAuthenticated,
      addToCart,
      removeFromCart,
      addToFavorites,
      removeFromFavorites,
      isInFavorites,
      createOrder,
      cancelOrder
    }}>
      {children}
    </AuthContext.Provider>
  );
};
